"""Interactive before/after for a repaired strip and a rejected grill profile."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'out/rmuc2027-tech-bars-review'
def main():
 data=json.loads((OUT/'review.json').read_text());data['bars']=json.loads((OUT/'bars.json').read_text());data['profile']=json.loads((OUT/'source-profile.json').read_text());data['verification']=json.loads((OUT/'verification.json').read_text())
 html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font:14px var(--font-sans,system-ui);line-height:1.5;color:var(--foreground,#ddd);margin:0}h2{font-size:21px;margin:0 0 8px}p{margin:8px 0 13px}.muted{color:var(--muted-foreground,#999)}.controls{display:flex;flex-wrap:wrap;gap:10px 14px;margin:15px 0}label{display:flex;gap:6px;align-items:center}select{font:inherit;color:inherit;background:var(--secondary,#333);border:1px solid var(--border,#666);border-radius:5px;padding:7px;max-width:100%}.note{padding:16px;background:var(--secondary,#222);border-radius:var(--radius,8px);font-size:13px;margin:13px 0}.counts{display:flex;gap:24px;flex-wrap:wrap;margin:13px 0}.counts b{font-size:24px;display:block}.counts span{font-size:12px;color:var(--muted-foreground,#999)}.canvas{padding:16px;background:#181818;border-radius:8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair img{width:100%;display:block}.label{font-size:12px;color:white;margin:5px 0}.wipe{position:relative;aspect-ratio:1;overflow:hidden}.wipe img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.seam{position:absolute;top:0;bottom:0;width:2px;background:#f3aa47}.badge{position:absolute;top:9px;background:#111d;color:white;padding:4px 6px;border-radius:3px;font-size:11px}.left{left:8px}.right{right:8px}.slider{display:flex;gap:9px;align-items:center;margin:9px 0;color:white;font-size:12px}.slider input{flex:1;accent-color:#f3aa47}.hidden{display:none}.small{font-size:12px}details{margin-top:15px;font-size:12px}table{width:100%;border-collapse:collapse}td,th{padding:7px;border-bottom:1px solid var(--border,#555);text-align:right}td:first-child,th:first-child{text-align:left}@media(max-width:480px){label,select{font-size:12px}.counts b{font-size:21px}.controls{gap:8px}.badge{font-size:9px}}
</style></head><body><h2>Tech Core · bar repair and grill trial</h2><p class="muted">The cut-off strip predates the recent runs: it is already damaged in the installed asset.</p><div class="controls"><label>Study <select id="study"><option value="repair">Repair cut-off bar</option><option value="grill">Simpler grill profile · rejected</option><option value="sourcecheck">Check repaired bar against STEP</option></select></label><label>Crop <select id="subject"><option value="bar">Bar close-up</option><option value="grill">Grill close-up</option><option value="face">Whole crucial face</option></select></label><label>View <select id="view"><option value="oblique">Oblique</option><option value="reverse">Reverse</option><option value="front">Front</option><option value="top">Top</option><option value="side">Side</option></select></label><label>Layout <select id="layout"><option value="pair">Side by side</option><option value="wipe">Wipe</option></select></label></div><div id="note" class="note"></div><div class="counts"><div><span id="countlabel"></span><b id="counts"></b></div><div><span id="changelabel"></span><b id="change"></b></div></div><div class="canvas"><div id="pair" class="pair"><div><div class="label" id="bl"></div><img id="pb" alt="Before"></div><div><div class="label" id="al"></div><img id="pa" alt="After"></div></div><div id="wipe" class="wipe hidden"><img id="wb" alt="Before"><img id="wa" alt="After"><div id="seam" class="seam"></div><span class="badge left" id="wbl"></span><span class="badge right" id="wal"></span></div><div id="slider" class="slider hidden"><span>Before</span><input id="position" type="range" min="0" max="100" value="50" aria-label="Comparison divider"><span>After</span></div></div><p class="small" id="metric"></p><p class="small muted">Matched 1200 × 1200 source-color diagnostic renders, with framing fixed by the STEP reference. Flat, two-sided shading; no simulated bloom or Bevy PBR. The white strips are non-emissive in rm-simulator. Materials, collision and installed assets are unchanged.</p><details><summary>Geometry and runtime findings</summary><table><thead><tr><th>Region / trial</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>White strip repair · current candidate</td><td>73</td><td>84</td></tr><tr><td>Whole Core · strip repair</td><td>11,601</td><td>11,612</td></tr><tr><td>Grill · STEP → precise planar trial</td><td>12,926</td><td>6,395</td></tr><tr><td>Grill · STEP → simple solid profiles</td><td>12,926</td><td>2,856</td></tr><tr><td>Current approximate grill region</td><td colspan="2">≈580 dark triangles; source ownership partly ambiguous</td></tr></tbody></table><p>The solid-profile trial keeps all 34 structural slots, 70 bores and 2 mm thickness. Slots have sharp corners and bores use hexagons; folded pieces develop seams. It is rejected as a speed improvement over the current approximation. Its source-only comparison changes this shell alone; every other STEP surface is exact.</p><p>Runtime inspection: Tech Core uses ordinary CAD materials. Armor and Rune lights clone materials selected by node name, ancestry and source RGB, then change base color/emission. Their fallback panels are suppressed when source bindings exist. Emission does not add a point light per strip. Preserve those bindings when simplifying optical geometry.</p></details><script>
const data=__DATA__,$=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US'),index=new Map(data.views.map(r=>[[r.subject,r.stage,r.view].join('|'),r]));const studies={repair:{before:'before',after:'bars',bl:'Before · current simplified candidate',al:'After · strip repaired',note:'The earlier simplification dropped painted side faces and part of the bar. The repair restores all four white strip groups from STEP and merges their planar faces. The complete shape costs 11 additional triangles per Core.',counts:'73 → 84',countlabel:'Selected strip triangles',change:'+11',changelabel:'Triangles per Core'},grill:{before:'source',after:'source-profile',bl:'Before · full STEP geometry',al:'Trial · simple solid profiles',note:'Rejected performance trial: 78% fewer triangles than the selected STEP shell, but 2,856 is still more than the roughly 580 triangles in the current approximation, and fold seams become visible. All slots, bores and sheet thickness remain. This is a source-only shape study, not an integrated runtime candidate.',counts:'12,926 → 2,856',countlabel:'Selected grill shell triangles',change:'−78%',changelabel:'Relative to STEP shell'},sourcecheck:{before:'source',after:'bars',bl:'Original STEP reference',al:'Repaired simplified candidate',note:'The restored strips follow the original STEP shape within 0.01 mm sampled deviation. The rest of this simplified face retains earlier approximations; this comparison is not a whole-face fidelity approval.',counts:'86 → 84',countlabel:'STEP → repaired white triangles',change:'<0.01 mm',changelabel:'Sampled strip surface error'}};
function row(stage){const r=index.get([$('subject').value,stage,$('view').value].join('|'));if(!r)throw Error('Missing matched render');return r}function wipe(){const p=$('position').value;$('wa').style.clipPath='inset(0 0 0 '+p+'%)';$('seam').style.left=p+'%'}function update(){const s=studies[$('study').value],b=row(s.before),a=row(s.after);for(const id of ['pb','wb'])$(id).src=b.image;for(const id of ['pa','wa'])$(id).src=a.image;for(const id of ['bl','wbl'])$(id).textContent=s.bl;for(const id of ['al','wal'])$(id).textContent=s.al;$('note').textContent=s.note;$('counts').textContent=s.counts;$('countlabel').textContent=s.countlabel;$('change').textContent=s.change;$('changelabel').textContent=s.changelabel;const pair=$('layout').value==='pair';$('pair').classList.toggle('hidden',!pair);$('wipe').classList.toggle('hidden',pair);$('slider').classList.toggle('hidden',pair);const m=data.verification.finite_view_white_mask[$('subject').value];$('metric').textContent=$('study').value==='grill'?'Approximate profile trial; apertures retained, visible fold seams prevent adoption.':$('view').value==='oblique'?'White pixels missing versus STEP in this crop: '+fmt(m.before.lost)+' before → '+fmt(m.bars.lost)+' after. Raster-mask check, not an all-view certificate.':'';wipe()}for(const id of ['study','subject','view','layout'])$(id).onchange=update;$('position').oninput=wipe;$('pa').onload=()=>console.log('After image '+$('pa').naturalWidth+'×'+$('pa').naturalHeight);update();console.log('Matched renders: '+index.size);</script></body></html>'''
 (OUT/'review.html').write_text(html.replace('__DATA__',json.dumps(data)))
 # Image paths are already absolute so T3 can inline the local artifacts.
 (OUT/'review-inline.html').write_text(html.replace('__DATA__',json.dumps(data)))
if __name__=='__main__':main()
